import impl


def test_rounding_carry_promotes_to_next_unit():
    result = impl.format_bytes(999950)
    match = re.match(r'([\d.]+)\s*([a-zA-Z]+)', result.strip())
    assert match, f"unexpected format: {result!r}"
    value, unit = float(match.group(1)), match.group(2)
    assert unit == 'MB', f"rounding carried to unit boundary but unit was not promoted: {result!r}"
    assert abs(value - 1.0) < 0.01, f"expected ~1.0 MB after promotion, got {result!r}"
    assert 'kB' not in result, f"should not display carried-over value in old unit: {result!r}"
